package br.com.loja.pedidos.common;

import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;

/** Algo que o site identifica por um código (forma de entrega, cupom, nível do clube, forma de pagamento). */
public interface Coded {

    String code();

    static <T extends Coded> Map<String, T> index(Collection<T> items) {
        Map<String, T> byCode = new LinkedHashMap<>();
        items.forEach(item -> byCode.put(item.code(), item));
        return byCode;
    }
}
package br.com.loja.pedidos.common;

import org.springframework.http.HttpStatus;

public class DomainException extends RuntimeException {

    private final String code;
    private final HttpStatus status;

    public DomainException(String code, HttpStatus status) {
        super(code);
        this.code = code;
        this.status = status;
    }

    public static DomainException unprocessable(String code) {
        return new DomainException(code, HttpStatus.UNPROCESSABLE_ENTITY);
    }

    public static DomainException conflict(String code) {
        return new DomainException(code, HttpStatus.CONFLICT);
    }

    public static DomainException notFound(String code) {
        return new DomainException(code, HttpStatus.NOT_FOUND);
    }

    public String code() {
        return code;
    }

    public HttpStatus status() {
        return status;
    }
}
package br.com.loja.pedidos.common;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class Money {

    public static final BigDecimal ZERO = round(BigDecimal.ZERO);

    private Money() {
    }

    /** Arredondamento "meio para o par" em centavos. */
    public static BigDecimal round(BigDecimal value) {
        return value.setScale(2, RoundingMode.HALF_EVEN);
    }

    public static BigDecimal percent(BigDecimal base, BigDecimal rate) {
        return round(base.multiply(rate));
    }
}
package br.com.loja.pedidos.common;

import java.math.BigDecimal;

public enum Region {
    SOUTHEAST("0.01", null, 0),
    SOUTH("0.01", null, 0),
    MIDWEST("0.015", null, 0),
    NORTH("0.025", "30.00", 3),
    NORTHEAST("0.02", "30.00", 2);

    private final BigDecimal insuranceRate;
    private final BigDecimal insuranceCap;
    private final int carrierExtraDays;

    Region(String insuranceRate, String insuranceCap, int carrierExtraDays) {
        this.insuranceRate = new BigDecimal(insuranceRate);
        this.insuranceCap = insuranceCap == null ? null : new BigDecimal(insuranceCap);
        this.carrierExtraDays = carrierExtraDays;
    }

    public static Region parse(String code) {
        for (Region region : values()) {
            if (region.name().equals(code)) {
                return region;
            }
        }
        return null;
    }

    public BigDecimal insuranceFor(BigDecimal productsSubtotal) {
        BigDecimal insurance = Money.percent(productsSubtotal, insuranceRate);
        return insuranceCap != null && insurance.compareTo(insuranceCap) > 0 ? Money.round(insuranceCap) : insurance;
    }

    /** Dias a mais de despacho nas entregas feitas por transportadora. */
    public int carrierExtraDays() {
        return carrierExtraDays;
    }
}
package br.com.loja.pedidos.coupon;

import java.math.BigDecimal;

import org.springframework.stereotype.Component;

import br.com.loja.pedidos.common.Money;

@Component
public class Buy3Pay2Coupon implements Coupon {

    @Override
    public String code() {
        return "BUY3PAY2";
    }

    @Override
    public BigDecimal discount(CouponContext context) {
        BigDecimal discount = Money.ZERO;
        for (var line : context.lines()) {
            BigDecimal freeUnits = BigDecimal.valueOf(line.quantity() / 3);
            discount = discount.add(line.product().price().multiply(freeUnits));
        }
        return Money.round(discount);
    }
}
